CREATE DATABASE IF NOT EXISTS talent_inspirations CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE talent_inspirations;
CREATE TABLE IF NOT EXISTS companies(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(255) NOT NULL,career_url TEXT NOT NULL,logo_url TEXT NULL,industry VARCHAR(100) DEFAULT 'Other',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX idx_company_industry(industry));
CREATE TABLE IF NOT EXISTS job_sources(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,source_url TEXT NOT NULL,ats_type VARCHAR(50) DEFAULT 'generic',auto_sync BOOLEAN NOT NULL DEFAULT TRUE,last_checked_at TIMESTAMP NULL,status ENUM('active','paused','error') DEFAULT 'active',last_sync_found INT DEFAULT 0,last_sync_imported INT DEFAULT 0,FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS jobs(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,company_id BIGINT UNSIGNED NOT NULL,source_url TEXT NOT NULL,external_job_id VARCHAR(255) NULL,title VARCHAR(500) NOT NULL,description LONGTEXT NOT NULL,location VARCHAR(500) NULL,country VARCHAR(100) NOT NULL DEFAULT 'United States',state VARCHAR(150) NULL,city VARCHAR(150) NULL,location_type ENUM('remote','hybrid','onsite','unknown') DEFAULT 'unknown',experience_level ENUM('fresher','experienced','other') DEFAULT 'other',category VARCHAR(100) NULL,employment_type VARCHAR(80) NULL,apply_url TEXT NOT NULL,source_job_url TEXT NULL,posted_at DATETIME NULL,first_seen_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,expires_at DATETIME NOT NULL,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_job(company_id,external_job_id),INDEX idx_public(expires_at,is_active,posted_at),FOREIGN KEY(company_id) REFERENCES companies(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS job_skills(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,job_id BIGINT UNSIGNED NOT NULL,skill_name VARCHAR(150) NOT NULL,skill_type VARCHAR(80) DEFAULT 'technical',UNIQUE KEY uq_skill(job_id,skill_name),FOREIGN KEY(job_id) REFERENCES jobs(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS admin_users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,email VARCHAR(255) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin') DEFAULT 'admin',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
